INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('handels-kv-2027-streikfreigabe-oegb-warnstreiks-30-november','Handels-KV: ÖGB gibt Streiks frei, Entscheidung am 30.11.','Der ÖGB hat der GPA die Streikfreigabe für den Handel erteilt. Bringt die vierte Runde am 30. November keine Einigung, drohen Warnstreiks im Weihnachtsgeschäft.','Der **Handels-KV** steht vor der entscheidenden Runde: Der Österreichische Gewerkschaftsbund hat der Gewerkschaft GPA am 25. November die Freigabe für Streiks im Handel erteilt. Betroffen sind rund 420.000 Handelsangestellte in ganz Österreich. Bringt die vierte Verhandlungsrunde am 30. November keine Einigung, sollen erste Warnstreiks folgen – mitten im Weihnachtsgeschäft.

## Handels-KV 2027: Wo die Verhandlungen stehen

Drei Runden haben Gewerkschaft und Arbeitgeber bisher absolviert, ein Abschluss ist nicht in Sicht. Die dritte Runde am 17. November wurde nach rund sieben Stunden ohne Ergebnis unterbrochen. Schon zum Auftakt im Oktober lagen die Positionen weit auseinander, wie wir über die [erste Runde der Handels-KV-Verhandlungen](/artikel/handels-kv-2027-erste-runde-ohne-ergebnis-gpa-3-8-prozent) berichtet haben.

Das Angebot der Arbeitgeberseite ist laut GPA seit Wochen unverändert:

- 2,1 Prozent mehr Gehalt
- eine Einmalzahlung von 350 Euro

Die Gewerkschaft fordert dagegen ein Plus von 3,8 Prozent. Dazu kommen Forderungen nach besseren Arbeitsbedingungen, konkret Zuschläge für Mehrarbeit sowie für kurzfristiges Einspringen, wenn Kolleginnen oder Kollegen ausfallen.

## Betriebsversammlungen und Streikbeschlüsse

Nach der ergebnislosen dritten Runde hat die GPA in Handelsbetrieben in ganz Österreich Betriebsversammlungen abgehalten. Dort wurden vorsorglich Streikbeschlüsse gefasst. Vor der Verhandlung am 17. November hatten sich laut Gewerkschaft Hunderte Beschäftigte vor der Wirtschaftskammer versammelt, um ein besseres Angebot einzufordern.

Mit der Freigabe durch den ÖGB ist nun der formale Rahmen geschaffen, damit tatsächlich gestreikt werden kann. Wann, wo und in welcher Form erste Warnstreiks stattfinden würden, hat die Gewerkschaft noch nicht bekannt gegeben.

## Argumente beider Seiten

GPA-Verhandlungsleiterin Linda Keizer betont die Rolle der Beschäftigten für die umsatzstärkste Zeit des Jahres: Ein erfolgreiches Weihnachtsgeschäft „steht und fällt mit den Beschäftigten“. Sie fordert die Arbeitgeber auf, ihre Blockadehaltung aufzugeben und ein deutlich verbessertes Angebot vorzulegen. Aus Sicht der Gewerkschaft gleicht das bisherige Angebot nicht einmal die Teuerung aus.

Die Arbeitgeber verweisen laut GPA auf die schwierige Lage vieler Kleinstbetriebe. Die Gewerkschaft hält dem entgegen, dass mehr als die Hälfte des Umsatzes und fast 60 Prozent der Beschäftigten auf rund 100 große Unternehmen entfallen. Zudem verweist sie auf die laut WIFO anhaltende Erholung im Handel. Wie viel im heurigen Weihnachtsgeschäft auf dem Spiel steht, zeigt etwa die Prognose für die [Weihnachtseinkäufe in Wien](/artikel/weihnachtsgeschaeft-wien-2026-460-millionen-euro-geschenke).

## Andere Branchen haben bereits abgeschlossen

Während der Handel noch verhandelt, gibt es in mehreren anderen Branchen bereits Ergebnisse für 2027. So einigten sich etwa die Sozialpartner für die ausländischen Luftverkehrsgesellschaften auf ein Plus von 3,4 Prozent, auch in der Telekommunikation und in der Gebäudereinigung gibt es Abschlüsse. Ohne Ergebnis sind dagegen etwa noch die Verhandlungen für die IT-Branche und die privaten Busunternehmen.

## Was der Handels-KV für Beschäftigte bedeutet

Der Kollektivvertrag legt die Mindestgehälter für Angestellte im Handel fest und gilt damit für eine der größten Beschäftigtengruppen des Landes. Für Kundinnen und Kunden könnten Warnstreiks im Dezember kürzere Öffnungszeiten oder eingeschränkten Betrieb in einzelnen Geschäften bedeuten. Wer mehr über die eigene Position bei Lohnfragen wissen will, findet Hinweise in unseren [Tipps zur Gehaltsverhandlung](/artikel/gehaltsverhandlung-tipps-oesterreich-kollektivvertrag).

Ob es tatsächlich zu Arbeitsniederlegungen kommt, entscheidet sich am 30. November. Erst dann zeigt sich, ob die Arbeitgeberseite ihr Angebot nachbessert und eine Einigung vor dem Höhepunkt des Weihnachtsgeschäfts gelingt.','wirtschaft','Arbeit & Karriere',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/handels-kv-2027-streikfreigabe-oegb-warnstreiks-30-november.webp','ÖGB / Gewerkschaft GPA (OTS)','https://www.ots.at/presseaussendung/OTS_20261125_OTS0063/kv-handel-oegb-erteilt-streikfreigabe','published','2026-11-27T16:45:00.000Z','2026-11-27T16:45:04.538Z','Handels-KV: ÖGB erteilt Streikfreigabe','Handels-KV 2027: Der ÖGB hat Streiks für 420.000 Handelsangestellte freigegeben. Ohne Einigung am 30. November drohen Warnstreiks. Alle Fakten.','Handels-KV','["Handels-KV","Handels-KV 2027","Streik Handel","Warnstreik Handel Dezember","KV Handel Streikfreigabe","GPA Handel Verhandlung","Kollektivvertrag Handel 2027","Gehaltserhöhung Handel 2027"]','Handels-KV: Geschäft im Weihnachtsgeschäft mit leeren Kassen','Interior of an Austrian retail shop in the evening during Christmas season, empty checkout counters, shelves with goods, warm festive lights, quiet atmosphere, people only as blurred silhouettes in background, no text, no logos, no readable signs','[{"q":"Wann wird im Handel gestreikt?","a":"Das steht noch nicht fest. Erste Warnstreiks folgen laut GPA nur, wenn die vierte Verhandlungsrunde am 30. November keine Einigung bringt."},{"q":"Was bieten die Arbeitgeber im Handels-KV an?","a":"Laut Gewerkschaft 2,1 Prozent mehr Gehalt und eine Einmalzahlung von 350 Euro. Die GPA fordert 3,8 Prozent und Zuschläge für Mehrarbeit und kurzfristiges Einspringen."},{"q":"Wie viele Beschäftigte betrifft der Handels-KV?","a":"Rund 420.000 Handelsangestellte in ganz Österreich."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind,